INSERT OR IGNORE INTO knowledge (id,title,content) VALUES ('k_about','About Ferrn','Ferrn Digital Agency (ferrnagency.com) is a Nigerian digital agency serving clients in Nigeria, the UK, the US, Canada and beyond. It designs and builds conversion-focused websites, custom web applications (portals, dashboards, workflow systems), SaaS and internal business systems, UI/UX design, AI automation and integrations, e-commerce, hosting, maintenance and support. Operating principle: make money, save time, solve something worth solving. Email: info@ferrnagency.com. Booking: https://cal.com/ferrn-agency.');
INSERT OR IGNORE INTO knowledge (id,title,content) VALUES ('k_work','Selected work','Gromzia Ventures (logistics website), Synergix Africa (platform website), M-P Infrastructure (EPC corporate website), Insightblitz (Web3 growth website), Aroda (product ecosystem website), Fashion Fusion Africa (event website), Relay (freight revenue-control web app), PWAN EHA (AI chatbot for civic and legal guidance). Case studies are at /work.');
INSERT OR IGNORE INTO knowledge (id,title,content) VALUES ('k_process','How projects run','Discover → Define → Design → Build → Launch. Websites typically take a few weeks; web applications and AI systems are delivered in milestones. Ferrn provides post-launch support and maintenance plans.');
INSERT OR IGNORE INTO knowledge (id,title,content) VALUES ('k_pricing','Pricing guidance','Marketplace products have published prices at /marketplace (setup fee plus a monthly managed plan, or a code buyout). Custom websites and apps are quoted after a short discovery call. Never quote a custom price in chat; offer a call or the marketplace instead.');
INSERT OR IGNORE INTO knowledge (id,title,content) VALUES ('k_marketplace','Marketplace','Ready-built products with live demos: Clinic Front Desk, School Admissions Portal, Logistics Quote & Track, Clinic/School/Real Estate/Logistics websites, AI Website Assistant, WhatsApp Appointment Reminders, Lead Follow-up Autopilot. Plans: Launch (deployed for you), Managed (hosted and maintained monthly), Own the code (buyout licence).');
